import { readdir, readFile, lstat } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

// Explicit known runtime roots only; never traverse env/evidence/auth directories.
export async function releaseFiles(root, { runtime = false } = {}) {
  const files = ['LICENSE', 'package.json', 'package-lock.json'];
  if (!runtime) files.push('Dockerfile', '.dockerignore', '.gcloudignore');
  for (const dir of ['src', 'public']) {
    if (!(await lstat(resolve(root, dir))).isDirectory()) throw new Error('Release directory rejected');
    for (const name of await readdir(resolve(root, dir))) {
      const path = `${dir}/${name}`;
      if (!/^[a-z][a-z0-9-]*\.(?:js|html|css|svg)$/.test(name)) throw new Error(`Unexpected release filename: ${path}`);
      files.push(path);
    }
  }
  return Promise.all(files.sort().map(async file => {
    if (!(await lstat(resolve(root, file))).isFile()) throw new Error(`Release symlink/directory rejected: ${file}`);
    const bytes = await readFile(resolve(root, file));
    return { file, sha256: createHash('sha256').update(bytes).digest('hex') };
  }));
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const files = await releaseFiles(process.cwd(), { runtime: process.argv.includes('--runtime') });
  console.log(process.argv.includes('--json') ? JSON.stringify(files, null, 2) : files.map(item => item.file).join('\n'));
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createApp } from '../src/app.js';
import { validateReleaseCommit } from '../src/release.js';
import { releaseFiles } from '../scripts/release-files.js';

test('health reports validated release and foundation readiness without claiming raids or DB readiness', async () => {
  for (const length of [40, 64]) {
    const commit = 'a'.repeat(length);
    const response = await createApp({ releaseCommit: commit }).dispatch({ method: 'GET', path: '/health' });
    assert.deepEqual(JSON.parse(response.body), { status: 'ok', releaseCommit: commit, phase: 'foundation', readiness: 'not-ready-for-raids' });
  }
  assert.equal(validateReleaseCommit(undefined), null);
  assert.throws(() => validateReleaseCommit(undefined, { required: true }));
  for (const value of ['', 'main', 'abc1234', 'g'.repeat(40), 'A'.repeat(40), 'a'.repeat(40) + '\n', '<script>']) assert.throws(() => createApp({ releaseCommit: value }));
});
test('release inventory is runtime/build files only, with reproducible source parity hashes', async () => {
  const first = await releaseFiles(process.cwd()); const again = await releaseFiles(process.cwd());
  assert.deepEqual(first, again);
  assert.ok(first.some(item => item.file === 'src/server.js'));
  assert.ok(first.every(item => /^[a-f0-9]{64}$/.test(item.sha256)));
  assert.ok(first.every(item => !/^(?:test|test-support|scripts|node_modules|\.git|\.codex-evidence|\.env|secrets)/.test(item.file)));
  const runtime = await releaseFiles(process.cwd(), { runtime: true });
  assert.ok(runtime.every(item => !['Dockerfile', '.dockerignore', '.gcloudignore'].includes(item.file)));
  for (const name of ['.dockerignore', '.gcloudignore']) {
    const patterns = (await readFile(name, 'utf8')).split('\n').filter(line => line && !line.startsWith('#'));
    assert.equal(patterns[0], '**');
    assert.ok(!patterns.some(line => line.includes('test') || line.includes('simulator') || line.includes('evidence') || line.includes('node_modules')));
  }
});
FROM node:24.22.1-bookworm-slim
WORKDIR /app
ENV NODE_ENV=production PORT=8080
COPY package.json package-lock.json ./
RUN npm ci --omit=dev --ignore-scripts --no-audit --no-fund && npm cache clean --force
COPY src/ ./src/
COPY public/ ./public/
COPY LICENSE ./LICENSE
ARG RELEASE_COMMIT
ENV RELEASE_COMMIT=${RELEASE_COMMIT}
RUN node --input-type=module -e 'import { validateReleaseCommit } from "./src/release.js"; validateReleaseCommit(process.env.RELEASE_COMMIT, { required: true });'
LABEL org.opencontainers.image.revision=${RELEASE_COMMIT}
USER node
EXPOSE 8080
CMD ["node", "src/server.js"]
